imgbrowse_title: "Lihat isi image",
imgbrowse_explain: "Jelajahi image game atau paket apa pun yang dibaca ps5upload (.exfat, .ffpkg, .ffpfs, .ffpfsc, atau .pkg yang dibuat dengan kunci debug) di komputer mana pun, tanpa me-mount-nya. Simpan file atau folder ke komputer, atau ubah file dan tulis salinan yang diedit: image yang Anda buka tidak pernah diubah.",
