imgbrowse_undo: "Urungkan",
imgbrowse_copy_explain: "Salinan adalah image baru utuh dengan jenis yang sama, ditulis di samping aslinya dengan -edited di namanya, lalu dibaca ulang dan diperiksa. Lamanya kira-kira sama dengan mengonversi game. Yang asli tidak diubah.",
