imgbrowse_open_copy: "Lihat isi salinan",
localimage_explain: "Image dibuka sebagai drive biasa di komputer ini, sehingga Anda dapat menambah, mengganti, dan menghapus berkas di dalamnya — misalnya berkas patch — menggunakan Finder atau Explorer, persis seperti flash disk. Perubahan disimpan langsung ke berkas image. ps5upload tidak pernah menulis ke image itu sendiri; sistem operasi Andalah yang melakukannya. Keluarkan di sini bila sudah selesai.",
