"pkglib.installAll.what": "Apa itu “Pasang semua”?",
"pkglib.installAll.whatBody": "“Pasang semua” menjalankan setiap paket yang siap secara berurutan: game dasar → pembaruan → DLC. Bila Anda punya dua pembaruan dengan versi sama (atau dua paket DLC yang bentrok), gunakan kotak centang pada tiap baris untuk memilih mana yang harus dipasang konsol ini — hanya satu per grup. Hapus centang untuk melewati grup itu. Tombol Pasang pada satu baris selalu memasang paket itu saja.",
