// Editing a game image in place (ShadowMount+ checkout)
library_edit_files_tooltip: "Keluarkan image ini dari ShadowMount+ dan pasang dengan izin tulis agar kamu bisa menambah atau mengganti berkas di dalamnya",
library_edit_modal_run: "Ambil untuk diedit",
library_edit_confirm_title: "Edit image game ini?",
library_edit_confirm_body: "{name} akan dipindahkan keluar dari folder ShadowMount+ dan dipasang dengan izin tulis di {mountPoint}.\n\nSelama kamu mengedit, game hilang dari layar utama PS5. Game kembali setelah sesi edit selesai.\n\nMengubah berkas yang salah di dalam image game bisa membuatnya gagal dijalankan, dan tidak bisa dibatalkan. Cadangkan dulu kalau kamu ragu.",
library_edit_confirm_ok: "Ambil untuk diedit",
library_edit_needs_mount_point: "Pengeditan memerlukan titik pemasangan yang ditentukan. Perbarui helper PS5 ke versi yang mendukung pemilihan titik pemasangan.",
notif_library_edit_failed: "Gagal mengambil untuk diedit",
edit_session_title: "Mengedit {name}",
edit_session_body: "Selama sesi ini terbuka, game tetap tersembunyi dari layar utama PS5 — ShadowMount+ tidak melihat image di lokasinya sekarang. Selesaikan pengeditan untuk mengembalikannya.",
edit_session_open: "Buka berkas",
edit_session_finish: "Selesai mengedit",
edit_session_done: "Sesi edit selesai",
edit_session_done_body: "{name} sudah kembali ke folder aslinya. ShadowMount+ akan memasang dan mendaftarkannya lagi dalam waktu sekitar satu menit.",


// Name conflicts when pasting or adding files
fs_paste_conflict_title: "{count} item sudah ada di sini",
fs_paste_conflict_body: "Ganti {names}?\n\nFolder digabungkan, bukan dikosongkan: berkas di dalamnya yang tidak kamu tempel dibiarkan apa adanya. Berkas dengan nama sama akan ditimpa, dan itu tidak bisa dibatalkan.",
fs_paste_conflict_ok: "Ganti",

library_edit_files_short: "Edit berkas",

library_images_capabilities: "Pasang untuk bermain, atau pakai Edit berkas untuk mengubah isinya — menambah DLC, mengganti aset, atau menerapkan patch backport. Perubahan ditulis langsung ke image.",

library_edit_modal_title: "Edit isi \"{name}\"",
library_edit_modal_intro: "Pilih lokasi pemasangan selama kamu bekerja. Image dikeluarkan dari ShadowMount+ selama itu dan dikembalikan saat selesai — jadi game tersembunyi dari layar utama PS5 sampai saat itu.",
library_mount_tooltip_smp: "Serahkan image ini ke ShadowMount+, yang memasang dan mendaftarkannya agar bisa kamu mainkan (hanya-baca)",



helper_mismatch_title: "Helper PS5 v{payload}, tapi aplikasi ini v{app}",
helper_mismatch_send: "Kirim helper",
helper_mismatch_body_v3: "Tidak ada yang perlu dilakukan di PS5 itu sendiri: tekan Kirim helper dan aplikasi ini mengirim helper yang sesuai ke konsol. Sebelum itu, perbaikan dan fitur versi baru tidak akan berfungsi.",

"joberr.direct_staged_file_missing": "Unggahan ini sebenarnya sudah selesai, jadi tidak ada lagi yang perlu diterbitkan — dan berkas di PS5 kini hilang atau ukurannya salah. Unggah ulang dan pilih «Timpa», bukan «Lanjutkan».",
"joberr.direct_tx_corrupt": "PS5 mendeteksi kerusakan protokol pada transfer ini. Mulai ulang payload dari tab «Kirim payload», lalu coba lagi.",
"joberr.direct_writer_io_error": "PS5 kehabisan ruang kosong (atau drive eksternal terlepas) saat menulis berkas. Kosongkan ruang di drive tujuan lalu klik «Coba lagi» — unggahan berlanjut dari titik terakhir.",
"joberr.fs_delete_path_not_allowed": "PS5 menolak akses ke jalur tersebut. Gunakan /data/, /user/, atau jalur terpasang /mnt/ext* maupun /mnt/usb*.",
"joberr.fs_read_path_not_allowed": "Berkas ini berada di partisi sistem hanya-baca yang biasanya diblokir. Aktifkan Pengaturan → «Izinkan pengunduhan berkas sistem» untuk mengunduh dari /system, /system_data, dan jalur terlindungi lainnya.",
"joberr.fs_write_failed": "PS5 tidak dapat menulis ke tujuan di tengah transfer — biasanya drive penuh atau drive eksternal terlepas. Periksa ruang kosong atau pasang kembali drive, lalu klik «Coba lagi» (unggahan berlanjut dari titik terakhir).",
"joberr.fs_write_failed_no_space": "Drive tujuan kehabisan ruang (atau berkas terlalu besar untuk sistem berkas tersebut). Kosongkan ruang di PS5 atau drive eksternal — atau pilih tujuan lain — lalu klik «Coba lagi».",
"joberr.packed_unsupported": "Helper PS5 menolak transfer terpaket. Ini terjadi pada payload usang ketika unggahan folder menyusut menjadi satu berkas kecil (misalnya saat melanjutkan game dengan banyak berkas mungil). Perbarui ps5upload ke versi terbaru, kirim ulang payload dari tab «Kirim payload», lalu coba lagi.",
"joberr.preflight_insufficient_space": "Drive tujuan tidak punya cukup ruang kosong untuk berkas ini. Kosongkan ruang di PS5 (Pengaturan → Penyimpanan) atau pilih tujuan lain, lalu klik «Coba lagi».",
"joberr.size_mismatch": "Transfer belum selesai sebelum terputus — sebuah berkas di PS5 tidak lengkap sehingga tidak diterbitkan (salinan lama Anda, jika ada, tetap utuh). Biasanya ini berarti PS5 masuk mode istirahat atau kehilangan daya di tengah unggahan. Jaga konsol tetap menyala (Pengaturan → Sistem → Penghematan Daya → Waktu Sampai PS5 Mati), lalu jalankan lagi item ini: «Lanjutkan» hanya mengirim ulang berkas yang hilang, «Timpa» membuat salinan bersih.",
"joberr.ava1_stalled": "Transfer berhenti berjalan (sumber berhenti mengirim data). Coba lagi; jika berulang, periksa drive sumber atau berbagi jaringan.",
"joberr.tx_table_full": "Terlalu banyak transfer berjalan bersamaan di PS5. Tunggu beberapa selesai atau mulai ulang payload.",
"joberr.zip_unsupported": "File .zip ini memakai sesuatu yang tidak dapat di-stream oleh pengunggah (enkripsi, metode kompresi selain Deflate atau Stored, atau jalur berkas yang tidak aman atau ganda). Ekstrak di komputer Anda lalu unggah folder-nya.",
"joberr.sevenz_unsupported": "File .7z ini memakai metode kompresi atau fitur yang tidak dapat di-stream oleh pengunggah. Ekstrak di komputer Anda lalu unggah folder-nya.",
"joberr.sevenz_unsupported_layout": "File .7z ini menyimpan folder atau berkas kosong di antara berkasnya dalam satu blok solid, tata letak yang tidak dapat di-stream oleh pengunggah. Kemas ulang dengan 7-Zip, atau ekstrak lalu unggah folder-nya.",
"joberr.rar_unsupported": "File .rar ini memiliki jalur berkas ganda atau tidak aman, atau fitur yang tidak dapat di-stream oleh pengunggah. Ekstrak di komputer Anda lalu unggah folder-nya.",
"pkg.patch_did_not_apply": "PS5 menerima pembaruan ini lalu tidak melakukan apa pun dengannya — gim masih di versi sebelumnya. Artinya konsol tidak dapat mencocokkan pembaruan dengan gim dasar yang terpasang. Pasang ulang gim dasar melalui ps5upload dari paket dasar yang sesuai dengan pembaruan ini (pilih «Timpa»), lalu terapkan lagi.",
"pkglib.updateBaseUnknown.title": "Pembaruan ini mungkin tidak diterapkan",
"pkglib.updateBaseUnknown.installAnyway": "Tetap pasang",
"pkglib.updateBaseUnknown.body": "{id} sudah terpasang, tetapi bukan dari paket dasar yang dipasang ps5upload — jadi PS5 mungkin tidak bisa mencocokkan pembaruan ini dengannya. Bila itu terjadi, konsol melaporkan berhasil dan tidak mengubah apa pun. Jika setelahnya gim masih di versi lama, pasang paket dasar yang sesuai lewat ps5upload (pilih «Timpa»), lalu terapkan pembaruan ini lagi.",
"pkg.patch_regressed": "Menerapkan ulang pembaruan ini justru menghapusnya — game kembali ke versi dasarnya. Pemasang PS5 memperlakukan pembaruan yang diterapkan ulang sebagai pembaruan yang harus dibatalkan. Terapkan pembaruan sekali lagi untuk kembali ke versi terbaru, dan hindari memasang ulang pembaruan yang sudah dimiliki game.",
