"fpkg.lowSpace": "Ruang kosong sedikit: konversi bisa butuh hingga {need} di drive keluaran, yang punya {free}.",
"fpkg.about": "Arahkan ke folder game, atau ke image mount .exfat atau .ffpkg. Konverter membaca pohon berkas, memeriksa bahwa semua yang dibutuhkan paket yang bisa dijalankan tersedia, lalu menulis .pkg format debug ke folder keluaran.",
"fpkg.aboutWhere": "Konversi berjalan di mesin yang menjalankan engine — komputer ini, host Docker, atau perangkat Android — bukan di konsol. Tidak ada yang sampai ke konsol sampai kamu memasang paketnya — lewat stream dari komputer ini, atau diunggah ke PS5 dulu.",
"fpkg.aboutSource": "Sumber harus berupa pohon game yang sudah didekripsi. Instalasi retail tidak bisa dibongkar di sini, dan pemeriksaan di bawah akan memberi tahu jika itu yang kamu pilih.",
"fpkg.aboutChecks": "Yang dicari pemeriksaan",
"fpkg.checkEboot": "eboot.bin di akar pohon — modul judul. Harus berupa ELF mentah atau SELF terbungkus; modul bertanda tangan retail tidak bisa dikemas ulang.",
"fpkg.checkParam": "sce_sys/param.json, dan tanpa sce_sys/param.sfo — param.sfo mengarahkan jalur peluncuran konsol ke rute PS4.",
"fpkg.checkIcons": "ID konten 36 karakter, kedua ikon, dan modul hak sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Bahwa nilai DRM paket standar. Nilai gratis atau bisa-ditingkatkan membuat konsol mengunci judul; nilainya hanya ditulis ulang di paket, dan berkasmu sendiri tidak pernah diubah.",
"payloads_essentials_title": "Disarankan bersama ps5upload",
"payloads_essentials_body": "Jika kamu menyiapkan konsol untuk pertama kali, ketiga ini mencakup sebagian besar yang diharapkan ps5upload: kstuff-lite (patch kernel yang diandalkan kebanyakan homebrew), ShadowMount+ (mount image game dari penyimpanan), dan nanoDNS (menjauhkan konsol dari jalur pembaruan Sony). Selebihnya di daftar ini opsional.",
