volumes_store_pkg_copies: "Simpan salinan paket di sini",
volumes_pkg_copies_hint: "Fungsi pilihan ini: “Unggah & instal” lebih dulu menyalin file .pkg ke PS5, lalu menginstal dari salinan itu. Ini hanya menentukan drive mana yang menyimpan salinan tersebut. Ini tidak mengubah tempat game diinstal (PS5 menentukannya di pengaturan Penyimpanan miliknya), dan “Stream & instal” tidak menyimpan salinan sama sekali. Jika drive yang dipilih tidak terhubung, salinan masuk ke penyimpanan internal.",
