captures_title: "Tangkapan",
"arcpkg.choose": "Pilih arsip…",
"arcpkg.help": "Untuk .zip, .7z, atau .rar yang berisi satu atau beberapa berkas .pkg di folder mana pun. Hanya paket yang diekstrak, langsung ke PS5 (tidak ada yang diekstrak di komputer ini), lalu dipasang satu per satu: game dasar dulu, lalu pembaruannya, lalu DLC. RAR multi-bagian (.part1.rar, .part2.rar…) didukung: pilih bagian pertama dan simpan sisanya di sebelahnya. Kata sandi diminta saat RAR membutuhkannya; ZIP dan 7z berkata sandi tidak didukung.",
"arcpkg.keepsRunning": "Ini tetap berjalan jika Anda membuka layar lain, dan juga terlihat di Tugas.",
"arcpkg.notArchive": "Berkas itu bukan arsip .zip, .7z, atau .rar.",
