"arcpkg.title": "Pasang paket dari arsip",
"install.library.title": "Salinan paket di PS5",
"install.stream.file.help": "Pilih .pkg atau .fpkg, atau jatuhkan di mana saja pada jendela ini. Biarkan aplikasi terbuka sampai pemasangan selesai; progres terlihat di antrean di atas dan di Tugas.",
"install.stream.file.title": "Pasang berkas paket",
"install.tab.stream.lead": "PS5 memasang langsung dari komputer ini atau dari tautan. Tidak ada salinan yang ditaruh di PS5 lebih dulu, jadi tidak perlu ruang kosong di sana, dan ini cara pemasangan yang paling andal.",
"install.tab.upload.lead": "Paket disalin dulu ke PS5, lalu dipasang dari salinan itu. Gunakan ini saat PS5 tidak dapat menjangkau komputer ini (stream gagal dengan galat jaringan), atau untuk menyimpan paket di PS5 agar bisa dipasang ulang nanti tanpa komputer ini.",
"install.upload.file.browser": "Menyalin paket ke PS5 dari sini memerlukan aplikasi desktop. Di UI web, gunakan Stream & instal, atau pasang paket yang sudah ada di PS5 di bawah.",
"install.upload.file.help": "Pilih .pkg atau .fpkg. Salinan memerlukan ruang kosong di PS5 sebesar seluruh paket, dan tetap ada di daftar di bawah sampai Anda menghapusnya.",
"install.upload.file.title": "Salin paket ke PS5 dan pasang",
"linkcard.confirm.direct": "PS5 mengunduh sendiri paket dari tautan dan memasangnya. Komputer ini tidak diperlukan lagi setelah dimulai, dan progres terlihat di PS5 (Unduhan), bukan di sini. Jika PS5 tidak dapat menjangkau tautan, aplikasi akan meneruskannya melalui komputer ini. Memasang ulang di atas game yang sudah terpasang dapat menghapusnya jika pemasang Sony gagal. Gunakan hanya tautan paket yang Anda percayai dan berhak Anda pasang.",
"linkcard.confirm.download": "Komputer ini menyimpan seluruh paket ke disk dulu, lalu memasangnya ke PS5. Komputer harus tetap menyala sampai kedua langkah selesai, dan butuh ruang kosong untuk paket. Memasang ulang di atas game yang sudah terpasang dapat menghapusnya jika pemasang Sony gagal. Gunakan hanya tautan paket yang Anda percayai dan berhak Anda pasang.",
"linkcard.confirm.stream": "Komputer ini mengunduh paket dan langsung meneruskannya ke PS5, jadi harus tetap menyala dan terhubung sampai pemasangan selesai. Tidak ada yang disimpan ke disk. Memasang ulang di atas game yang sudah terpasang dapat menghapusnya jika pemasang Sony gagal. Gunakan hanya tautan paket yang Anda percayai dan berhak Anda pasang.",
"linkcard.confirm.title": "Pasang dari tautan ini?",
