"linkcard.mode.direct_body": "PS5 mengambil tautan itu sendiri. PS5 harus dapat menjangkau tautan dan alamatnya harus pendek (yang panjang dipendekkan oleh aplikasi, dan aplikasi harus tetap terbuka).",
"linkcard.mode.download": "Unduh ke sini dulu, lalu pasang",
