stop: "Hentikan",
activity_description_v2: "Semua yang sedang dan sudah dilakukan aplikasi di konsol Anda: unggahan, unduhan, pemasangan, dan operasi berkas. Hentikan atau ulangi yang mana pun dari sini. 100 yang terbaru disimpan, juga setelah dimulai ulang.",
fw_spoof_subtitle_v2: "Memeriksa apakah versi firmware yang dilaporkan PS5 ini telah diubah oleh payload spoof, sehingga Anda tahu versi sebenarnya sebelum memasang sesuatu yang bergantung padanya.",
health_subtitle_v2: "Memeriksa bahwa PS5, aplikasi ini, dan jaringan di antaranya berfungsi, memberi tahu apa yang perlu diperbaiki jika tidak, dan mengukur kecepatan transfer berkas di antara keduanya.",
remotePlay_subtitle_v2: "Siapkan PS5 ini untuk Remote Play dan dapatkan PIN yang menautkan aplikasi PS Remote Play ke konsol ini.",
saves_description_v2: "Data simpanan di PS5, satu entri per game. Cadangkan simpanan sebuah game ke .zip di komputer ini, dan pulihkan nanti.",
shell_description_v2: "Ketik perintah yang berjalan di PS5, di dalam proses helper. Untuk pengguna tingkat lanjut. Keluaran dibatasi 256 KB per perintah; panah atas dan bawah memanggil perintah sebelumnya.",
"arcpkg.links.go": "Unduh {count} berkas",
"arcpkg.links.help": "Tempel tautan langsung ke arsip, atau ke setiap bagian arsip yang dipecah, satu per baris. Berkas diunduh ke komputer ini (Downloads/ps5upload), yang perlu ruang untuk semuanya; lalu paket di dalamnya diekstrak ke PS5 seperti dijelaskan di atas.",
"arcpkg.links.kept": "{count} berkas yang diunduh ada di {dir}. Berkas itu disimpan agar Anda dapat mengulang pemasangan; hapus setelah selesai.",
"arcpkg.links.progress": "Mengunduh berkas {n} dari {count} ke komputer ini…",
"arcpkg.links.title": "Arsipnya ada di tautan unduhan",
"arcpkg.noFirstPart": "Berkas sudah diunduh, tetapi tidak ada yang merupakan bagian pertama arsip (.zip, .7z, .rar, atau .part1.rar). Periksa tautannya.",
"fpkg.image.done": "Image game sudah ditulis dan dibaca kembali. Salin ke drive PS5 (Unggah) dan ShadowMount+ akan me-mount-nya.",
"fpkg.image.what": "Satu file yang kamu salin ke drive PS5, yang di-mount ShadowMount+ dan ditampilkan di layar beranda. Tidak ada yang dipasang.",
"fpkg.image.folderOnly": "Hanya folder game di komputer ini yang bisa dijadikan image game.",
"fpkg.image.folderOnly_v2": "Hanya folder game (di komputer ini, server tersimpan, atau PS5) yang bisa menjadi image game.",
"fpkg.image.folderOnly_v4": "Hanya folder game, image game, atau arsip (.zip, .7z, .rar) yang berisi game yang dapat dijadikan image game; arsip diekstrak terlebih dahulu ke folder output.",
"fpkg.card.make": "② Apa yang dibuat",
"fpkg.card.options_v2": "③ Opsi",
"fpkg.card.run_v2": "④ Buat & pasang",
"fpkg.options.image": "Image",
"fpkg.make.pkg_title": "Paket (.pkg)",
"fpkg.make.pkg_body": "Terpasang di PS5 seperti game dari toko, di-stream dari sini atau diunggah dulu. Game PS4 jalan di firmware apa pun; game PS5 di 11.60 ke bawah.",
"fpkg.make.image_title": "Image game",
"fpkg.make.image_body": "Satu berkas di drive PS5 yang di-mount ShadowMount+ dan tampil di layar utama. Tidak ada yang dipasang, dan jalan di firmware yang tidak bisa menjalankan paket PS5.",
"fpkg.make.recommended": "Disarankan",
"fpkg.make.recommended_fw": "Disarankan di FW {fw}",
"fpkg.make.pick_game": "Periksa game di ①, pilihan yang lebih cocok untuk PS5 Anda akan ditandai.",
"fpkg.make.why_image": "Game PS5 ini bisa dipasang sebagai paket tapi tidak jalan di FW {fw}; sebagai image, jalan.",
"fpkg.make.why_pkg": "Paket adalah pilihan biasa: terpasang dan jalan seperti game lain.",
