connection_payload_engine_unreachable: "Aplikasi tidak dapat menjangkau engine miliknya sendiri di komputer ini, jadi tidak tahu apakah helper sudah berjalan di PS5. Ini bukan masalah PS5: pemberitahuan di bagian atas jendela menjelaskan sebabnya dan dapat memulai ulang engine. Lalu tekan Kirim helper lagi. ({error})",
"engine_problem.missing.fix": "Pulihkan ps5upload-engine dari karantina antivirus Anda (atau izinkan), atau instal ulang aplikasi.",
"engine_problem.missing.why": "Program engine tidak ada di folder aplikasi. Perangkat lunak keamanan terkadang mengarantinanya.",
"engine_problem.port.fix": "Tekan Mulai ulang engine. Jika gagal, izinkan ps5upload-engine di firewall atau antivirus, lalu mulai ulang aplikasi.",
"engine_problem.port.why": "Sesuatu memakai alamat engine ({url}) tetapi tidak menjawab: program lain di port itu, atau perangkat lunak keamanan yang memblokir koneksi ke sana.",
"engine_problem.proxy.fix": "Matikan proxy atau alat VPN untuk alamat lokal (127.0.0.1), atau jalankan aplikasi tanpa pengaturan http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "Permintaan ke engine dikirim ke proxy yang diatur di komputer ini, bukan ke engine.",
"engine_problem.remote.fix": "Periksa bahwa engine (kontainer Docker atau komputer lain) berjalan dan dapat dijangkau di alamat itu, atau ubah di Pengaturan.",
"engine_problem.remote.why": "Engine yang diatur untuk aplikasi ini ({url}) tidak menjawab.",
"engine_problem.restart": "Mulai ulang engine",
"engine_problem.slow.fix": "Tekan Mulai ulang engine. Firewall atau antivirus yang menyaring koneksi lokal juga bisa menyebabkannya: izinkan ps5upload-engine.",
"engine_problem.slow.why": "Engine berjalan tetapi tidak menjawab.",
"engine_problem.stopped.fix": "Tekan Mulai ulang engine. Jika berhenti lagi, layar Log menunjukkan sebabnya.",
"engine_problem.stopped.why": "Engine tidak berjalan: berhenti, atau tidak pernah dimulai.",
"engine_problem.title": "Aplikasi tidak dapat menjangkau engine-nya di komputer ini",
"engine_problem.web.fix": "Periksa bahwa server (kontainer Docker) berjalan, lalu muat ulang halaman ini.",
"engine_problem.web.why": "Halaman ini kehilangan koneksi ke server ps5upload asalnya.",
gate_engine_down_body_v2: "Layar ini membutuhkan engine aplikasi, yang tidak menjawab. Pemberitahuan di bagian atas jendela menjelaskan sebabnya dan dapat memulai ulangnya.",
"profile.np.body": "Membuat PS5 memperlakukan akun yang sedang masuk sebagai sudah masuk ke PlayStation Network, tanpa menghubungi Sony. Beberapa fitur konsol hanya terbuka untuk akun yang sudah masuk, termasuk Remote Play. Memakai np-fake-signin buatan earthonion, yang diambil dari halaman proyeknya saat Anda menekan tombol.",
"profile.np.confirm_title": "Masukkan akun ini?",
"profile.np.failed": "Proses masuk tidak berjalan",
"profile.np.fetching": "Mengambil np-fake-signin…",
"profile.np.sending": "Mengirim ke PS5…",
"profile.np.sent": "np-fake-signin {version} berjalan di PS5. Mulai ulang PS5 untuk menyelesaikan; setelah itu akun tampil sebagai sudah masuk, dan Pengaturan > Sistem > Remote Play dapat dinyalakan.",
"profile.np.sign_in": "Masuk",
"profile.np.state_loading": "Membaca akun…",
"profile.np.state_no_slot": "Tidak ada akun di atas yang bernama {user}, jadi np-fake-signin akan berhenti. Beri akun nama yang sama dengan pengguna yang masuk, atau aktifkan satu akun untuknya.",
"profile.np.state_no_user": "Tidak ada pengguna yang masuk di PS5. Masuk ke profil yang Anda inginkan, lalu kembali.",
"profile.np.state_not_activated": "{user} (akun {slot}) belum memiliki ID akun. Aktifkan dulu di Akun di atas.",
"profile.np.state_ready": "Siap: {user} (akun {slot}) sudah diaktifkan.",
"profile.np.step_activate": "Akun memerlukan ID akun. Akun yang terhubung ke PSN sudah memilikinya; jika tidak, aktifkan di Akun di atas (aktivasi offline).",
"profile.np.step_run": "Tekan Masuk saat pengguna itu sedang masuk di PS5. Program berjalan sekali lalu keluar.",
"profile.np.title": "Masuk ke PlayStation Network (offline)",
