install_path_fallback_hint: "Upaya terakhir untuk paket yang sudah ada di PS5, ketika PS5 menolaknya dari penyimpanannya sendiri dan juga tidak bisa mengambilnya dari komputer ini. Hanya dipakai untuk game dasar yang belum terpasang, jadi tidak bisa menghapus apa pun. Belum terbukti: berhasil di firmware 11.20 dan ditolak di 13.60. Jika kamu mencobanya, tolong laporkan apakah berhasil.",
