"rp_dualsense": "Efek DualSense",
"rp_dualsense_hint": "Dengan DualSense yang terhubung ke komputer ini: pemicu adaptif, dan haptik saat terhubung lewat USB. Berlaku mulai dari awal berikutnya.",
"rp_mic_setting": "Mikrofon (eksperimental)",
