"rp_settings": "Pengaturan",
"rp_running_elsewhere": "Main sedang berjalan di {name}",
"rp_show_here": "Tampilkan di sini",
"rp_running_elsewhere_body": "Dimulai dari jendela lain atau sebelum halaman ini dimuat ulang, dan masih berjalan.",
"rpg_user_title": "Masuk ke pengguna di PS5",
"rpg_user_body": "Di konsol, pilih pengguna yang akan Anda pakai untuk bermain. Tidak perlu ada yang tetap di depan layar, tetapi pengguna harus sudah masuk. Gunakan pengguna tanpa kode sandi masuk: kode sandi menghentikan proses masuk otomatis saat konsol dinyalakan.",
"rpg_account_title": "Beri pengguna itu ID akun",
"rpg_account_body": "Remote Play dipasangkan dengan ID akun. Pengguna yang terhubung ke PlayStation Network sudah memilikinya; pengguna offline perlu diberi satu di Pengguna di atas (ID apa pun bisa; catat ID-nya, data simpanan yang dibuat setelahnya terikat padanya).",
"rpg_signin_title": "Masukkan akun ke PlayStation Network (offline)",
"rpg_signin_body": "PS5 hanya mengizinkan akun yang sudah masuk memakai Remote Play. Jika pengaturan Remote Play di konsol itu sendiri berwarna abu-abu, jalankan proses masuk offline di bawah (tidak ada yang dikirim ke Sony), lalu mulai ulang PS5. Ini bisa dibatalkan.",
"rpg_signin_fix": "Ke proses masuk",
"rpg_service_title": "Nyalakan Remote Play",
"rpg_service_body": "Pengaturan › Sistem › Remote Play › Aktifkan Remote Play. Aplikasi bisa menyalakannya untuk Anda, dan di firmware 10.00 dan yang lebih baru juga mengizinkannya untuk pengguna ini. Jika lalu Mulai mengatakan Remote Play mati, nyalakan di Pengaturan PS5 itu sendiri: yang berlaku adalah sakelar di konsol.",
"rpg_rest_title": "Izinkan PS5 dinyalakan dari mode istirahat",
"rpg_rest_body": "Pengaturan › Sistem › Penghematan Daya › Fitur yang Tersedia di Mode Istirahat: nyalakan «Tetap Terhubung ke Internet» dan «Aktifkan Menyalakan PS5 dari Jaringan». Tanpa keduanya, konsol dalam mode istirahat tidak bisa dinyalakan dan jaringannya tidur setelah beberapa detik. Hanya konsol yang bisa menampilkan pengaturan ini.",
"rpg_pair_title": "Pasangkan aplikasi ini dengan konsol",
"rpg_pair_body": "Koneksi › Nyalakan & masuk › Atur. Satu klik mendaftarkan aplikasi ini ke PS5 (seperti memasangkan aplikasi PS Remote Play) dan menyimpan kuncinya di komputer ini. Streaming, menyalakan, dan masuk semuanya memakainya; lakukan lagi setelah mengatur ulang konsol atau mengganti pengguna.",
"rpg_play_title": "Main",
"rpg_play_body": "Buka Remote Play lalu tekan Mulai: aplikasi menyalakan konsol jika sedang istirahat, masuk, lalu melakukan streaming. Bermainlah dengan pengontrol yang tersambung ke komputer ini, keyboard, atau sentuhan. Untuk memakai aplikasi PS Remote Play dari Sony atau chiaki-ng, minta PIN di bawah lalu masukkan di sana.",
"rpg_play_fix": "Buka Remote Play",
"rpg_title": "Siapkan Remote Play",
"rpg_progress": "{done} dari {n} langkah yang diperiksa selesai",
"rpg_on_console": "periksa di konsol",
"rpg_trouble": "Jika masih tidak berhasil",
"rpg_t_start_q": "Mulai berwarna abu-abu di layar Main.",
"rpg_t_start_a": "Aplikasi ini belum dipasangkan dengan konsol itu: lakukan langkah 6 (Koneksi › Nyalakan & masuk › Atur).",
"rpg_t_pair_q": "Saat mengatur pemasangan, muncul pesan bahwa tidak ada pengguna yang masuk dengan akun yang sudah diaktifkan.",
"rpg_t_pair_a": "Langkah 1 dan 2: masuk ke pengguna di PS5 dan beri ID akun, lalu coba lagi.",
"rpg_t_grey_q": "Pengaturan Remote Play di PS5 itu sendiri berwarna abu-abu.",
"rpg_t_grey_a": "Akun belum masuk ke PlayStation Network. Jalankan proses masuk offline (langkah 3) dan mulai ulang PS5.",
"rpg_t_wake_q": "Konsol tidak menyala, atau menyala tetapi tetap di layar pemilihan pengguna.",
"rpg_t_wake_a": "Periksa langkah 5 di konsol. Pengguna dengan kode sandi masuk menghentikan proses masuk otomatis. Jika konsol diatur ulang atau penggunanya berganti, atur pemasangan lagi (langkah 6).",
"rpg_t_black_q": "Gambar tetap hitam, tersendat, atau suaranya berderak.",
"rpg_t_black_a": "Gunakan koneksi kabel atau Wi-Fi 5 GHz untuk PS5 dan komputer ini, dan coba 720p atau 30 fps di pengaturan Remote Play. Firewall di komputer ini harus mengizinkan aplikasi di jaringan lokal (Remote Play memakai port TCP dan UDP 9295–9304). Di browser, gunakan Chrome, Edge, atau Safari terbaru: gambar memerlukan WebCodecs.",
"rpg_t_busy_q": "Muncul pesan bahwa PS5 masih menyelesaikan sesi terakhir, atau konsol lain sedang streaming.",
"rpg_t_busy_a": "Hanya satu konsol yang di-stream sekaligus, dan PS5 butuh hingga 30 detik setelah sesi berakhir. Hentikan stream yang lain, tunggu sebentar, lalu tekan Mulai lagi.",
"rpg_t_restrict_q": "Setelah masuk offline, game meminta menonaktifkan pembatasan konsol.",
"rpg_t_restrict_a": "Gunakan Batalkan masuk di halaman ini lalu mulai ulang, atau cabut pembatasannya di Pengaturan › Keluarga dan Kontrol Orang Tua › Pembatasan Konsol PS5 (kode sandi 0000 kecuali Anda mengubahnya).",
