"mesh_rp_started": "{name} mulai bermain di konsol ini",
"rp_keys_body3": "Klik gambar untuk bermain dengan keyboard; Esc mengembalikan penunjuk. Klik dua kali untuk layar penuh; di sana Esc singkat adalah Lingkaran dan menahan Esc keluar dari layar penuh. Tombol, suara, dan lainnya di Pengaturan.",
