"dump_decrypt_risk": "Dekripsi bisa membekukan konsol",
"dump_decrypt_risk_body": "Untuk dekripsi, helper sebentar menukar bagian sistem yang dipakai semua program untuk tiap file eksekusi. Jika game membaca berkas saat itu, konsol bisa beku dan perlu dimatikan paksa. Tetap di layar awal game selama proses. Hanya firmware hingga 13.60; di firmware lebih baru dump berupa salinan biasa.",
